with (R/'tables/dataset_inventory.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fields);w.writeheader();w.writerows(rows)
(R/'tables/dataset_inventory.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2))
header=f'''# 候选数据集总表（第一阶段）\n\n审计日期：2026-10-11。{len(rows)} 个版本/子资源条目，{len(set(x['family_id'] for x in rows))} 个研究/资源家族；同一家族不计独立来源。覆盖遗传、药物、组合药物和免疫刺激。此前项目只有README，未发现已有调研可复用；Replogle K562/RPE1与sciPlex3均保留。\n\n完整逐字段表见 [dataset_inventory.csv](dataset_inventory.csv) / [JSON](dataset_inventory.json)。未知不是不存在；公开链接不是本轮亲自读过数据文件。counts指UMI矩阵，raw reads另述；模型支持loader不等于原模型论文实际采用。\n\n本表先保存，再进行统一深入审计。第一阶段筛选理由不是最终推荐；第二阶段结论见审计报告和推荐清单。论文全文/GEO/Zenodo受到代理限制时，结论限定为作者代码或整合代码证据。所有精确细胞数注明文档/版本/统计范围，未用细胞数推断独立实验重复。\n\n|ID / 来源家族|背景与干预|采用证据与用途|进一步核查|\n|---|---|---|---|\n'''
def esc(s):return str(s).replace('|','/').replace('\n',' ')
for r in rows:
 header+='|'+ '|'.join(esc(x) for x in [r['dataset_id']+' / '+r['family_id'],r['cell_background']+'；'+r['intervention_type'],r['model_benchmark_evidence']+'；'+r['use_role'],r['deep_audit']+'；'+r['screening_reason']])+'|\n'
header+='''\n普通图谱、基础模型语料、bulk和其他模态见 [另列资源](../non_core_resources.md)，不计入上述家族数。\n'''
(R/'tables/dataset_inventory.md').write_text(header)
print('Saved',len(rows),'rows;',len(set(r['family_id'] for r in rows)),'independent families')
